:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #17252a;
  background: #d9e5dc;
  font-synthesis: none;
}

* { box-sizing: border-box; }
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 48px 18px;
  display: grid;
  place-items: center;
  background-color: #d9e5dc;
  background-image: radial-gradient(#b9cfc1 1px, transparent 1px);
  background-size: 20px 20px;
}
button, input { font: inherit; }
.board {
  width: min(100%, 570px);
  padding: 32px;
  background: #fffdf5;
  border: 3px solid #17252a;
  box-shadow: 8px 8px 0 #17252a;
}
.board-header { display: flex; align-items: center; gap: 16px; margin-bottom: 24px; }
.pixel-clock {
  width: 58px; height: 58px; display: grid; place-items: center;
  color: #fffdf5; background: #df6b4c; border: 3px solid #17252a;
  font-size: 30px; line-height: 1; box-shadow: 3px 3px 0 #17252a;
}
.eyebrow { margin: 0 0 4px; color: #4e6963; font-size: 0.78rem; font-weight: 800; letter-spacing: .13em; }
h1 { margin: 0; font-size: clamp(1.65rem, 6vw, 2.1rem); line-height: 1.1; }
.summary {
  display: flex; align-items: center; gap: 9px; padding: 12px 14px;
  background: #eaf1e8; border: 2px solid #c7d7ca; font-weight: 700;
}
.status-dot { width: 10px; height: 10px; border-radius: 50%; background: #498c68; box-shadow: 0 0 0 3px #c8dfcf; }
.summary-note { margin-left: auto; color: #60736d; font-size: .88rem; font-weight: 500; }
.alarm-form { display: grid; grid-template-columns: 1fr 1.4fr; gap: 16px; margin: 24px 0 30px; }
.time-fields { display: flex; align-items: end; gap: 8px; }
.field { display: grid; gap: 7px; min-width: 0; }
.field label { font-size: .9rem; font-weight: 750; }
.field label span { color: #687a74; font-weight: 500; }
input {
  width: 100%; min-height: 48px; padding: 9px 11px;
  color: #17252a; background: #fff; border: 2px solid #9eb1a5; border-radius: 2px;
}
input::placeholder { color: #87958f; }
input:focus-visible, button:focus-visible { outline: 3px solid #df6b4c; outline-offset: 3px; }
.time-fields .field { flex: 1; }
.time-fields input { text-align: center; }
.time-colon { padding-bottom: 10px; font-size: 1.5rem; font-weight: 800; }
.label-field { grid-column: 1 / -1; }
.add-button {
  grid-column: 1 / -1; min-height: 50px; border: 2px solid #17252a;
  color: #fffdf5; background: #17252a; font-weight: 750; cursor: pointer;
  transition: transform .12s, box-shadow .12s, background .12s;
}
.add-button span { margin-right: 6px; font-size: 1.25rem; vertical-align: -1px; }
.add-button:hover { background: #30474a; box-shadow: 3px 3px 0 #df6b4c; }
.add-button:active { transform: translate(2px, 2px); box-shadow: none; }
.list-heading { display: flex; align-items: center; gap: 10px; padding-bottom: 11px; border-bottom: 2px solid #dce5dc; }
h2 { margin: 0; font-size: 1.15rem; }
.total-badge { min-width: 27px; padding: 2px 8px; text-align: center; border: 1px solid #b9c9bc; background: #eaf1e8; font-size: .85rem; font-weight: 750; }
.empty-state { margin: 20px 0 10px; color: #61736c; text-align: center; }
.alarm-list { display: grid; gap: 10px; margin: 14px 0 0; padding: 0; list-style: none; }
.alarm-row {
  display: grid; grid-template-columns: 1fr auto auto; align-items: center; gap: 12px;
  min-height: 72px; padding: 12px 14px; background: #f3f5eb; border: 2px solid #d8e1d5;
}
.alarm-row.is-off { opacity: .62; }
.alarm-time { font-variant-numeric: tabular-nums; font-size: 1.55rem; font-weight: 800; letter-spacing: .03em; }
.alarm-name { overflow-wrap: anywhere; color: #60736d; font-size: .9rem; }
.switch-control { display: flex; align-items: center; gap: 8px; font-size: .85rem; font-weight: 700; cursor: pointer; }
.switch-control input { width: 22px; min-height: 22px; height: 22px; margin: 0; accent-color: #498c68; cursor: pointer; }
.delete-button { min-width: 42px; min-height: 42px; border: 2px solid transparent; color: #9e4935; background: transparent; font-size: 1.3rem; cursor: pointer; }
.delete-button:hover { border-color: #df6b4c; background: #fff0e8; }
.delete-button:active { transform: scale(.94); }
footer { margin-top: 26px; color: #687a74; text-align: center; font-size: .85rem; }
footer span { color: #df6b4c; }
@media (max-width: 460px) {
  body { padding: 24px 14px; }
  .board { padding: 23px 18px; box-shadow: 5px 5px 0 #17252a; }
  .alarm-form { grid-template-columns: 1fr 1fr; gap: 13px 10px; }
  .alarm-row { grid-template-columns: 1fr auto auto; gap: 7px; padding: 10px 8px; }
  .alarm-time { font-size: 1.35rem; }
  .switch-control { gap: 5px; }
}

const form = document.querySelector('#alarm-form');
const hourInput = document.querySelector('#alarm-hour');
const minuteInput = document.querySelector('#alarm-minute');
const labelInput = document.querySelector('#alarm-label');
const list = document.querySelector('#alarm-list');
const emptyState = document.querySelector('#empty-state');
const enabledCount = document.querySelector('#enabled-count');
const alarmTotal = document.querySelector('#alarm-total');

let alarms = [];
let nextId = 1;

function render() {
  alarms.sort((a, b) => a.hour - b.hour || a.minute - b.minute || a.id - b.id);
  list.replaceChildren();
  emptyState.hidden = alarms.length > 0;
  alarmTotal.textContent = String(alarms.length);
  enabledCount.textContent = String(alarms.filter(alarm => alarm.enabled).length);

  for (const alarm of alarms) {
    const item = document.createElement('li');
    item.className = `alarm-row${alarm.enabled ? '' : ' is-off'}`;

    const details = document.createElement('div');
    const time = document.createElement('div');
    time.className = 'alarm-time';
    time.textContent = `${String(alarm.hour).padStart(2, '0')}:${String(alarm.minute).padStart(2, '0')}`;
    const name = document.createElement('div');
    name.className = 'alarm-name';
    name.textContent = alarm.label || 'No label';
    details.append(time, name);

    const toggleLabel = document.createElement('label');
    toggleLabel.className = 'switch-control';
    const toggle = document.createElement('input');
    toggle.type = 'checkbox';
    toggle.checked = alarm.enabled;
    toggle.setAttribute('aria-label', `Turn ${alarm.label || time.textContent} alarm ${alarm.enabled ? 'off' : 'on'}`);
    toggle.addEventListener('change', () => {
      alarm.enabled = toggle.checked;
      render();
    });
    const toggleText = document.createElement('span');
    toggleText.textContent = alarm.enabled ? 'On' : 'Off';
    toggleLabel.append(toggle, toggleText);

    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'delete-button';
    remove.textContent = '×';
    remove.setAttribute('aria-label', `Delete ${alarm.label || time.textContent} alarm`);
    remove.addEventListener('click', () => {
      alarms = alarms.filter(entry => entry.id !== alarm.id);
      render();
    });

    item.append(details, toggleLabel, remove);
    list.append(item);
  }
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const hour = Number(hourInput.value);
  const minute = Number(minuteInput.value);
  if (!Number.isInteger(hour) || hour < 0 || hour > 23 || !Number.isInteger(minute) || minute < 0 || minute > 59) return;

  alarms.push({ id: nextId++, hour, minute, label: labelInput.value.trim(), enabled: true });
  form.reset();
  hourInput.focus();
  render();
});

render();
